import { test, expect } from '@playwright/test';

test.describe('User Profile Update Confirmation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000/profile');
    await page.waitForLoadState('networkidle');
  });

  test('should display confirmation message after updating profile name', async ({ page }) => {
    // Fill in the profile name field
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('John Doe');

    // Click the save button
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify confirmation message appears
    const confirmationMessage = page.getByText(/profile updated successfully/i);
    await expect(confirmationMessage).toBeVisible();
    await expect(confirmationMessage).toHaveClass(/success/);
  });

  test('should display confirmation message after updating profile email', async ({ page }) => {
    // Fill in the email field
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('john.doe@example.com');

    // Click the save button
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify confirmation message appears
    const confirmationMessage = page.getByText(/profile updated successfully/i);
    await expect(confirmationMessage).toBeVisible();
  });

  test('should display confirmation message after updating profile bio', async ({ page }) => {
    // Fill in the bio field
    const bioInput = page.getByLabel('Bio');
    await bioInput.fill('Software engineer and tech enthusiast');

    // Click the save button
    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify confirmation message appears and contains expected text
    const confirmationMessage = page.getByText(/profile updated successfully/i);
    await expect(confirmationMessage).toBeVisible();
    await expect(confirmationMessage).toContainText('successfully');
  });

  test('should dismiss confirmation message when close button is clicked', async ({ page }) => {
    // Update profile
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('Jane Doe');

    const saveButton = page.getByRole('button', { name: /save/i });
    await saveButton.click();

    // Verify confirmation message appears
    const confirmationMessage = page.getByText(/profile updated successfully/i);
    await expect(confirmationMessage).toBeVisible();

    // Click close button on confirmation message
    const closeButton = page.getByRole('button', { name: /close/i }).first();
    await closeButton.click();

    // Verify confirmation message is hidden
    await expect(confirmationMessage).not.toBeVisible();
  });
});
